import csv
import re
from dataclasses import dataclass
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from pathlib import Path


@dataclass(frozen=True)
class Event:
    category: str
    amount: Decimal
    timestamp: str | None = None


def parse_timestamp(text: str) -> datetime:
    """Parse an aware ISO timestamp, validating offsets before normalization."""
    if not isinstance(text, str) or not text:
        raise ValueError('timestamp must be a nonempty ISO timestamp with a timezone')
    offset = re.search(r'(?:Z|[+-](?P<hour>[0-9]{2})(?::?(?P<minute>[0-9]{2}))?)$', text)
    if offset is None:
        raise ValueError(f'invalid timestamp or missing timezone: {text!r}')
    if offset.group('hour') is not None:
        if int(offset.group('hour')) >= 24 or int(offset.group('minute') or '0') >= 60:
            raise ValueError(f'invalid timestamp offset: {text!r}')
    try:
        timestamp = datetime.fromisoformat(text.removesuffix('Z') + ('+00:00' if text.endswith('Z') else ''))
        if timestamp.utcoffset() is None:
            raise ValueError('timestamp must include a timezone')
        return timestamp.astimezone(timezone.utc)
    except (ValueError, OverflowError) as error:
        raise ValueError(f'invalid aware ISO timestamp: {text!r}') from error


def load_events(path: str | Path) -> list[Event]:
    with open(path, newline='', encoding='utf-8') as stream:
        events = []
        for line, row in enumerate(csv.DictReader(stream), start=2):
            amount = row.get('amount')
            if amount is None or not amount.strip():
                raise ValueError(f'row {line}: missing or empty amount')
            try:
                value = Decimal(amount)
            except InvalidOperation as error:
                raise ValueError(f'row {line}: invalid amount {amount!r}') from error
            events.append(Event(row['category'], value, row.get('timestamp')))
        return events

