import csv
import re
from dataclasses import dataclass
from datetime import datetime, timezone
from decimal import Decimal
from pathlib import Path


@dataclass(frozen=True)
class Event:
    category: str
    amount: Decimal
    timestamp: str | None = None


_ISO_OFFSET = re.compile(r'(?P<offset>[+-]\d{2}:?\d{2})$')


def parse_timestamp(text: str) -> datetime:
    """Parse an ISO timestamp with an explicit timezone and normalize it to UTC."""
    if not isinstance(text, str) or not text.strip():
        raise ValueError('timestamp must be a non-empty ISO timestamp with a timezone')

    value = text.strip()
    # Validate numeric offset components explicitly; fromisoformat versions have
    # differed in how permissively they handle out-of-range offsets.
    match = _ISO_OFFSET.search(value)
    if match:
        offset = match.group('offset')
        digits = offset[1:].replace(':', '')
        hours, minutes = int(digits[:2]), int(digits[2:])
        if hours > 23 or minutes > 59:
            raise ValueError(f'invalid timestamp offset: {offset}')

    try:
        parsed = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith(('Z', 'z')) else value)
    except (TypeError, ValueError) as error:
        raise ValueError(f'invalid timestamp: {text!r}') from error
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError('timestamp must include a timezone offset')
    return parsed.astimezone(timezone.utc)


def load_events(path: str | Path) -> list[Event]:
    with open(path, newline='', encoding='utf-8') as stream:
        events = []
        for line, row in enumerate(csv.DictReader(stream), start=2):
            category = row.get('category')
            raw_amount = row.get('amount')
            if category is None or not category.strip():
                raise ValueError(f'row {line}: missing category')
            if raw_amount is None or not raw_amount.strip():
                raise ValueError(f'row {line}: missing amount')
            try:
                amount = Decimal(raw_amount)
            except (ValueError, ArithmeticError) as error:
                raise ValueError(f'row {line}: invalid amount {raw_amount!r}') from error
            events.append(Event(category, amount, row.get('timestamp')))
        return events

