from .parse import Event, parse_timestamp


def summarize(events: list[Event], *, since: datetime | None = None,
              until: datetime | None = None) -> dict:
    bounds = []
    for name, bound in (('since', since), ('until', until)):
        if bound is not None:
            if not isinstance(bound, datetime) or bound.tzinfo is None or bound.utcoffset() is None:
                raise ValueError(f'{name} bound must be a timezone-aware datetime')
            bounds.append(bound.astimezone(timezone.utc))
        else:
            bounds.append(None)
    since_utc, until_utc = bounds
    if since_utc is not None and until_utc is not None and since_utc >= until_utc:
        raise ValueError('since must be earlier than until')

    totals: dict[str, Decimal] = {}
    count = 0
    for event in events:
        if since_utc is not None or until_utc is not None:
            if event.timestamp is None:
                raise ValueError('event is missing timestamp required for time-window filtering')
            timestamp = parse_timestamp(event.timestamp)
            if since_utc is not None and timestamp < since_utc:
                continue
            if until_utc is not None and timestamp >= until_utc:
                continue
        totals[event.category] = totals.get(event.category, Decimal('0')) + event.amount
        count += 1
    return {'count': count,
            'totals': {key: str(totals[key]) for key in sorted(totals)}}
